const recs=$input.all().map(i=>i.json).filter(x=>x&&Object.keys(x).length);
if(recs.some(x=>x.error))return [{json:{mode:'READ_ONLY',result:'BLOCKED',reason:'ESPOCRM_CAMPAIGN_LIST_FAILED',canSend:false}}];
const result=[],seen=new Set();
for(const c of recs){
 if(typeof c.id!=='string'||!c.id||seen.has(c.id))throw Error('INVALID_OR_DUPLICATE_CAMPAIGN');
 seen.add(c.id);
 const active=c.status==='Active',enabled=c.masterSendingEnabled===true,
   chatwootProvider=String(c.ageProvider||'').toLowerCase().includes('chatwoot');
 const reasons=[];
 if(!active)reasons.push('CAMPAIGN_INACTIVE');
 if(!enabled)reasons.push('MASTER_SENDING_NOT_VERIFIED_FOR_CAMPAIGN');
 if(!chatwootProvider)reasons.push('CHATWOOT_PROVIDER_NOT_CONFIRMED');
 if(typeof c.ageTemplateName!=='string'||!c.ageTemplateName)reasons.push('TEMPLATE_NOT_CONFIRMED');
 if(typeof c.ageTemplateLanguage!=='string'||!c.ageTemplateLanguage)reasons.push('LANGUAGE_NOT_CONFIRMED');
 // Cannot attest audience/current consent without authoritative CRM policy API.
 reasons.push('RECIPIENT_POLICY_NOT_EVALUATED','PORTFOLIO_LEDGER_NOT_EVALUATED');
 result.push({id:c.id,name:String(c.name||'').slice(0,90),status:c.status||null,
   previewDecision:reasons.length?'BLOCKED':'CHECK_FURTHER',reasons});
}
return [{json:{checkedAt:new Date().toISOString(),mode:'READ_ONLY',campaignCount:recs.length,
 activeCount:recs.filter(x=>x.status==='Active').length,
 preview:result.slice(0,50),previewTruncated:result.length>50,recipientEligibilityVerified:false,
 canSend:false,crmEventWriteAuthorized:false}}];
